{
  "verdict": "hold",
  "conviction": "medium",
  "risk_band": "moderate",
  "window_band": "medium",
  "headline": "A late-stage, high-income neighborhood with rising wages but a -2.9% employment contraction and net out-migration of 11,517 returns caps near-term demand upside.",
  "reasoning": [
    {
      "observation": "The tract exhibits classic late-stage gentrification markers (stage 6-7): median household income of $165,179, median home value of $1,629,900, and 79% of residents holding a bachelor's degree or higher. There is minimal upward-arc appreciation potential remaining — this is a stability/preservation market, not a momentum market.",
      "sources": ["US Census ACS via Census Reporter (ACS 2024 5-year)"]
    },
    {
      "observation": "County employment fell -2.9% year-over-year as of 2025 Q4, a meaningful contraction that is a leading indicator of demand softening. This is the single most concerning demand-side signal: fewer employed residents means a shrinking pool of qualified buyers and renters.",
      "sources": ["BLS QCEW (2025 Q4, county totals)"]
    },
    {
      "observation": "Average weekly wages rose 4.6% year-over-year to $1,242, partially offsetting the employment decline. Those who remain employed are earning more, which provides some price support at the high end, but wage growth cannot fully compensate for a shrinking employment base.",
      "sources": ["BLS QCEW (2025 Q4, county totals)"]
    },
    {
      "observation": "The county recorded a net out-migration of 11,517 tax returns (IRS SOI 2021-2022). Critically, inflow AGI per return ($94,892) only marginally exceeds outflow AGI per return ($92,760), meaning the households leaving are nearly as affluent as those arriving — there is no meaningful income-upgrading migration dynamic to support further price appreciation.",
      "sources": ["IRS SOI county migration (2021-2022)"]
    },
    {
      "observation": "Mortgage originations grew only 2.1% year-over-year, and the denial rate stands at 31.9% — nearly one in three applications rejected. This elevated denial rate signals constrained credit access that caps the effective buyer pool, particularly relevant at the $1.6M+ price point where jumbo underwriting standards are stricter.",
      "sources": ["CFPB HMDA Data Browser (2024, county aggregations)"]
    }
  ],
  "minority_signals": [
    {
      "signal": "Mortgage originations did grow 2.1% year-over-year, indicating some positive purchase demand momentum.",
      "note": "The growth rate is marginal and is offset by a 31.9% denial rate and the broader employment contraction; it does not constitute a strong demand-building signal."
    },
    {
      "signal": "Wage growth of 4.6% YoY supports purchasing power for employed residents.",
      "note": "Wage gains are outpaced by the demand-dampening effect of a -2.9% employment decline and net out-migration; the foundation is narrowing even as remaining earners do better."
    }
  ]
}

